<script setup>
import {ref,onMounted,computed} from 'vue';import {useRoute} from 'vue-router';import {useWorkspace} from './stores/workspace.js';import Icon from './components/Icon.vue';import Dialog from './components/Dialog.vue';
const store=useWorkspace(),route=useRoute(),menu=ref(false),help=ref(false),notifications=ref(false);const nav=[{to:'/',label:'Overview',icon:'LayoutDashboard'},{to:'/shipments',label:'Shipments',icon:'Package'},{to:'/analytics',label:'Analytics',icon:'ChartNoAxesCombined'}];const initials=computed(()=>store.settings.name.split(' ').map(v=>v[0]).slice(0,2).join(''));
onMounted(()=>store.load());
</script>
<template><div class="app-shell"><aside class="sidebar" :class="{open:menu}"><RouterLink to="/" class="brand" @click="menu=false"><span class="brand-mark"><Icon name="Package" :size="23"/></span>dispatch<span class="brand-dot">.</span></RouterLink><button class="workspace-switch" @click="help=true"><span class="workspace-letter">N</span><span>{{store.settings.company}}<small>Demo workspace</small></span><Icon name="ChevronDown" :size="14"/></button><span class="nav-label">WORKSPACE</span><nav><RouterLink v-for="n in nav" :to="n.to" :class="{selected:route.path===n.to}" @click="menu=false"><Icon :name="n.icon"/>{{n.label}}<span v-if="n.label==='Shipments'" class="nav-count">{{store.shipments.length}}</span></RouterLink></nav><div class="sidebar-bottom"><div class="demo-card"><span class="demo-dot"></span><b>Your logistics, simplified.</b><p>A little more visibility.<br>A lot less guesswork.</p><button @click="help=true">Explore this demo<Icon name="ArrowUpRight" :size="15"/></button></div><RouterLink class="sidebar-link" to="/settings" @click="menu=false"><Icon name="Settings"/>Settings</RouterLink><button class="sidebar-link" @click="help=true;menu=false"><Icon name="HelpCircle"/>Help & project info</button><div class="profile"><span class="avatar">{{initials}}</span><span>{{store.settings.name}}<small>Workspace admin</small></span><RouterLink to="/settings" aria-label="Profile settings"><Icon name="ChevronDown" :size="15"/></RouterLink></div></div></aside><button v-if="menu" class="sidebar-overlay" @click="menu=false" aria-label="Close menu"></button><div class="main-shell"><header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu" @click="menu=!menu" aria-label="Open navigation"><Icon name="Menu"/></button><span>Workspace</span><Icon name="ChevronRight" :size="13"/><b>{{route.meta.title}}</b></div><div class="top-actions"><span class="demo-label"><i></i>Demo environment</span><button class="icon-button notification-button" @click="notifications=!notifications" :aria-expanded="notifications" aria-label="Notifications"><Icon name="Bell"/><i v-if="store.totals.delayed"></i></button><RouterLink to="/settings" class="avatar small" aria-label="Open profile">{{initials}}</RouterLink></div><div v-if="notifications" class="notification-pop"><b>Workspace notifications</b><p v-if="store.totals.delayed"><Icon name="CircleAlert"/>{{store.totals.delayed}} shipments need your attention.</p><p v-else>All clear. No delayed shipments.</p><RouterLink to="/shipments?status=Delayed" @click="notifications=false">Review shipments →</RouterLink></div></header><main><div v-if="store.storageWarning" class="warning" role="status">{{store.storageWarning}}</div><div v-if="store.loading" class="loading-state" aria-live="polite"><div class="skeleton title-skeleton"></div><div class="skeleton-grid"><div v-for="n in 4" class="skeleton"></div></div><div class="skeleton big-skeleton"></div><p>Loading your workspace…</p></div><div v-else-if="store.error" class="empty-state error-panel" role="alert"><Icon name="CircleAlert" :size="40"/><h2>We couldn’t load the workspace</h2><p>{{store.error}}</p><button class="btn primary" @click="store.load()"><Icon name="RefreshCw"/>Try again</button></div><RouterView v-else/></main><footer class="app-footer"><span>Dispatch © 2026 <i>·</i> Built for the journey.</span><span>Portfolio demo <i>·</i> Vue 3 + JavaScript</span></footer></div><Transition name="toast"><div v-if="store.toast" class="toast-message" role="status"><Icon name="CircleCheck"/>{{store.toast}}<button @click="store.toast=''" aria-label="Dismiss notification"><Icon name="X" :size="15"/></button></div></Transition><Dialog v-if="help" title="A workspace built to explore." @close="help=false"><p class="info-copy">Dispatch is a frontend portfolio project for managing international freight. All customers, shipments and figures are fictional.</p><div class="info-block"><b>Try it out</b><p>Create a shipment, search and filter the list, open its timeline, update a status and explore the analytics. Changes are saved in this browser.</p></div><div class="info-block"><b>Under the hood</b><p>Vue 3 Composition API · Pinia · Vue Router · Vite · JavaScript. No backend or live tracking service is connected.</p></div><button class="btn" @click="help=false;store.load(true)"><Icon name="CircleAlert"/>Preview the service error state</button></Dialog></div></template>
